"""Manually annotated browser-test fixtures. Never invoked by the application."""
import os
from pathlib import Path
if os.environ.get('TALENTIQ_TEST_FIXTURE')!='1' or 'talentiq-ui-' not in str(Path(os.environ.get('TALENTIQ_DATA_DIR','')).resolve()):
    raise RuntimeError('Synthetic fixture writes require an isolated TalentIQ browser-test directory.')

from backend.db import Session, Candidate, Document, Evaluation, Profile, Project, audit
from backend.schemas import AnalysisResponse
from backend.scoring import score_result

with Session() as db:
    candidates=db.query(Candidate).order_by(Candidate.name).all()
    for i,c in enumerate(candidates):
        profile=db.get(Profile,db.get(Project,c.project_id).profile_id)
        docs=db.query(Document).filter_by(candidate_id=c.id).all();d=docs[0]
        ev={'document_id':d.id,'page':1,'quote':'Built production services using Python.'}
        education={'document_id':d.id,'page':1,'quote':'Computer Science degree documented.'}
        response=AnalysisResponse.model_validate({'facts':[{'kind':'Skill','value':'Python','evidence':ev},{'kind':'Employment','value':'Built production Python services (synthetic test statement)','evidence':ev},{'kind':'Education','value':'Computer Science degree (synthetic test statement)','evidence':education}], 'assessments':[{'criterion_id':'skills','status':'Supported','score':90-i*10,'explanation':'Manually annotated synthetic test evaluation; not generated by production AI.','evidence':[ev]},{'criterion_id':'experience','status':'Supported','score':80-i*10,'explanation':'Synthetic test annotation for source-backed service development.','evidence':[ev]},{'criterion_id':'education','status':'Supported','score':75,'explanation':'Synthetic degree statement requires real-world verification.','evidence':[education]}], 'requirements':[{'requirement_index':0,'status':'Supported','explanation':'Synthetic CV states Python service development.','evidence':[ev]}], 'warnings':['SYNTHETIC BROWSER TEST FIXTURE — not a real candidate or a real model evaluation.'], 'interview_questions':['Describe the architecture of the documented Python service.']})
        result=score_result(profile.config,[response],{(doc.id,page['page']):page['text'] for doc in docs for page in doc.pages})
        c.details={'facts':result['facts']};c.status='Needs Review'
        if i==1:
            from backend.understanding import merge_briefs,VERSION
            reading={'version':VERSION,'summary':{'text':'Synthetic CV states Python services and a Computer Science degree.','evidence':[ev,education]},'work_history':[],'qualifications':[{'kind':'Skill','text':'Python service development','support':'demonstrated','evidence':[ev]},{'kind':'Education','text':'Computer Science degree documented.','support':'listed','evidence':[education]}],'clarifications':['Clarify the employer and dates; these are not stated.'],'interview_questions':['Describe the documented Python service architecture.'],'omitted_items':0}
            c.details={**c.details,'cv_brief':merge_briefs([reading],docs,'synthetic-annotated-fixture-only')}

        db.add(Evaluation(candidate_id=c.id,profile_id=profile.id,profile_version=profile.version,profile_snapshot={**profile.config,'profile_id':profile.id},model='synthetic-annotated-fixture-only',score=result['score'],coverage=result['coverage'],result=result,duration=1.2+i))
        audit(db,'Application','Synthetic annotated UI-test fixture added',c.name,c.project_id)
    db.commit()
